package com.example.discovery.registry.service;import static org.assertj.core.api.Assertions.*;import com.example.discovery.registry.config.RegistryProperties;import com.example.discovery.registry.model.RegisterServiceRequest;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;
class ServiceRegistryServiceTest{RegisterServiceRequest req(int p){return new RegisterServiceRequest("payment-service","payment-service-"+p,"localhost",p,"http://localhost:"+p+"/actuator/health");}@Test void registersMultipleInstancesAndHeartbeatAndRemoval(){var s=new ServiceRegistryService(new RegistryProperties(Duration.ofSeconds(10)));s.register(req(8081));s.register(req(8082));assertThat(s.findByServiceName("payment-service")).hasSize(2);var hb=s.heartbeat("payment-service","payment-service-8081");assertThat(hb.instanceId()).isEqualTo("payment-service-8081");s.deregister("payment-service","payment-service-8082");assertThat(s.findByServiceName("payment-service")).extracting("port").containsExactly(8081);}@Test void duplicateRegistrationReplacesInstance(){var s=new ServiceRegistryService(new RegistryProperties(Duration.ofSeconds(10)));s.register(req(8081));s.register(req(8081));assertThat(s.findByServiceName("payment-service")).hasSize(1);}@Test void expiresInstancesByTtl()throws Exception{var s=new ServiceRegistryService(new RegistryProperties(Duration.ofMillis(20)));s.register(req(8081));Thread.sleep(40);s.expireInstances();assertThat(s.findByServiceName("payment-service")).isEmpty();}@Test void handlesBasicConcurrentRegistrations()throws Exception{var s=new ServiceRegistryService(new RegistryProperties(Duration.ofSeconds(10)));try(var executor=Executors.newFixedThreadPool(8)){for(int i=0;i<50;i++){int port=8000+i;executor.submit(()->s.register(req(port)));}executor.shutdown();assertThat(executor.awaitTermination(5,TimeUnit.SECONDS)).isTrue();}assertThat(s.findByServiceName("payment-service")).hasSize(50);}}
